-- cachy-dots · look, feel, input
-- Managed by the installer; put your own tweaks in ~/.config/hypr/user.lua

-----------------------
---- LOOK AND FEEL ----
-----------------------
hl.config({
    general = {
        gaps_in     = 4,
        gaps_out    = 10,
        border_size = 2,
        -- border colors: cachy/theme.lua (generated by cachy-theme)
        resize_on_border = true,
        allow_tearing    = true, -- lets games opt into tearing (see window rule below)
        layout           = "dwindle",
    },

    decoration = {
        rounding         = 8,
        rounding_power   = 2,
        active_opacity   = 1.0,
        inactive_opacity = 0.96,
        shadow = {
            enabled      = true,
            range        = 8,
            render_power = 3,
        },
        blur = {
            enabled  = true,
            size     = 5,
            passes   = 2,
            vibrancy = 0.17,
        },
    },

    animations = { enabled = true },

    dwindle = { preserve_split = true },
    master  = { new_status = "master" },

    misc = {
        force_default_wallpaper = 0,
        disable_hyprland_logo   = true,
        vrr                     = 2, -- adaptive sync for fullscreen games
    },

    input = {
        kb_layout    = "us",
        follow_mouse = 1,
        sensitivity  = 0,
        accel_profile = "flat", -- raw mouse input, nicer for games
        touchpad = { natural_scroll = true },
    },
})

-- Animations: tuned to feel snappy (~150–250 ms), not floaty.
-- Material-style "decelerate" curves: fast start, gentle stop, so windows feel instantly responsive.
-- `speed` is in tenths of a second (2.5 = 250 ms). Tweak live with HyprMod's curve editor (Super+,).
hl.curve("md3_decel",  { type = "bezier", points = { {0.05, 0.7}, {0.1, 1}    } })
hl.curve("md3_accel",  { type = "bezier", points = { {0.3, 0},    {0.8, 0.15} } })
hl.curve("menu_decel", { type = "bezier", points = { {0.1, 1},    {0, 1}      } })
hl.curve("menu_accel", { type = "bezier", points = { {0.38, 0.04},{1, 0.07}   } })
hl.curve("linear",     { type = "bezier", points = { {0, 0},      {1, 1}      } })

hl.animation({ leaf = "global",           enabled = true, speed = 10,  bezier = "default" })
hl.animation({ leaf = "windowsIn",        enabled = true, speed = 2.5, bezier = "md3_decel",  style = "popin 85%" })
hl.animation({ leaf = "windowsOut",       enabled = true, speed = 1.8, bezier = "md3_accel",  style = "popin 85%" })
hl.animation({ leaf = "windowsMove",      enabled = true, speed = 2.5, bezier = "md3_decel" })
hl.animation({ leaf = "border",           enabled = true, speed = 3,   bezier = "md3_decel" })
hl.animation({ leaf = "fade",             enabled = true, speed = 2,   bezier = "md3_decel" })
hl.animation({ leaf = "layersIn",         enabled = true, speed = 2,   bezier = "menu_decel", style = "slide" })
hl.animation({ leaf = "layersOut",        enabled = true, speed = 1.5, bezier = "menu_accel", style = "slide" })
hl.animation({ leaf = "workspaces",       enabled = true, speed = 2.5, bezier = "menu_decel", style = "slide" })
hl.animation({ leaf = "specialWorkspace", enabled = true, speed = 2.5, bezier = "md3_decel",  style = "slidevert" })

hl.gesture({ fingers = 3, direction = "horizontal", action = "workspace" })

